// first, with who made them and the projects they reach. Owners see all;
// user_id narrows it to one person's.
func (q *Queries) ListAgentConnections(ctx context.Context, arg ListAgentConnectionsParams) ([]ListAgentConnectionsRow, error) {
	rows, err := q.db.Query(ctx, listAgentConnections, arg.OrgID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAgentConnectionsRow{}
	for rows.Next() {
		var i ListAgentConnectionsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.UserName,
			&i.UserEmail,
			&i.UserRole,
			&i.Name,
			&i.AllProjects,
			&i.Scopes,
			&i.CreatedAt,
			&i.ExpiresAt,
			&i.LastUsedAt,
			&i.LastTool,
			&i.ClientKind,
			&i.ClientRef,
			&i.ProjectNames,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

